111	// summaryColumns returns, for each non-empty rendered row, the rune offset at
112	// which the summary begins (i.e. the column after the padded invocation).
113	func summaryColumns(t *testing.T, commands []experimentalCommandInfo) []int {
114		t.Helper()
115		var cols []int
116		for _, line := range strings.Split(renderExperimentalCommands(commands), "\n") {
117			if line == "" {
118				continue
119			}
120			info := indexOfSummary(t, line, commands)
121			cols = append(cols, info)
122		}
123		return cols
124	}
