126	// indexOfSummary finds the rune offset of a row's summary text within the line.
127	func indexOfSummary(t *testing.T, line string, commands []experimentalCommandInfo) int {
128		t.Helper()
129		for _, info := range commands {
130			if idx := strings.Index(line, info.Summary); idx >= 0 {
131				return utf8.RuneCountInString(line[:idx])
132			}
133		}
134		t.Fatalf("no known summary found in rendered line %q", line)
135		return -1
136	}
