178	func TestRenderExperimentalCommands_MultiByteInvocationAligns(t *testing.T) {
179		t.Parallel()
180	
181		// "entire ▶▶" is 9 runes but 13 bytes (each ▶ is 3 bytes). The longest
182		// invocation below is 12 runes, so the column width is 12. With byte-based
183		// padding, len("entire ▶▶") == 13 >= 12 would skip padding and misalign the
184		// row; rune-based padding correctly adds 3 spaces.
185		commands := []experimentalCommandInfo{
186			{Invocation: "entire aaaaa", Summary: "first"},
187			{Invocation: "entire ▶▶", Summary: "second"},
188		}
189	
190		if got := len("entire ▶▶"); got < 12 {
191			t.Fatalf("test precondition broken: byte length %d should exceed column width 12", got)
192		}
193	
194		cols := summaryColumns(t, commands)
195		if cols[0] != cols[1] {
196			t.Fatalf("multi-byte invocation summary misaligned: %v", cols)
197		}
198	}
